-- Disposable PostgreSQL schema for the owned application stop-loss probe.
-- This seed is intentionally small and never used by production configuration.
create table t_core_user (id varchar(64) primary key, username varchar(100), password varchar(120), orgid varchar(64), orgname varchar(100), status varchar(20), lastsuspendedflag varchar(1), expirydate timestamp, parentorgid varchar(64));
create table t_core_role (id bigint primary key, lastsuspendedflag varchar(1));
create table t_core_role_user (roleid bigint, userid varchar(64));
create table t_core_role_permission (roleid bigint, permissiontypeid varchar(64), targetid varchar(64));
create table t_core_menu (id varchar(64) primary key, parentid varchar(64), name varchar(100));
create table t_core_org (id varchar(64) primary key, orgname varchar(100), parentid varchar(64), sampledepartment varchar(100));
create table t_core_user_permission (userid varchar(64), permissiontypeid varchar(64), targetid varchar(64));
create table t_core_login_config (id varchar(64) primary key, loginorg varchar(1), loginrole varchar(1), logintenant varchar(1), loginauthmethod varchar(36), captcha varchar(1), addomainsupport varchar(1), showloginauthoption varchar(1), qccode varchar(1));
create table t_core_password_policy (id bigint primary key, maxfailedattempts bigint, expiryinterval bigint, expiredpolicy varchar(36), lastsuspendedflag varchar(1));
create table t_emc_emp (id varchar(64) primary key, username varchar(100), createdtime timestamp, orgid varchar(64), age integer, sex varchar(10), mobile varchar(100), remark varchar(100), customfield varchar(100));
create table t_emc_org_permission (permissiontypeid varchar(64), targetid varchar(64), orgid varchar(64));
create table t_emc_equipt_category (id varchar(64) primary key, equiptcategory varchar(100));
create table t_emc_equipt (id bigint primary key, equiptid varchar(64), equiptname varchar(100), specification varchar(100), factoryno varchar(100), manufacturer varchar(100), status varchar(36), equiptcategoryid varchar(64), useddepartmentid varchar(64), useddepostid varchar(64), sharing varchar(36), maintain varchar(36), sourcemethod varchar(36), sourcedate date, equiptbelong varchar(36), maintainuserid varchar(64), keepuserid varchar(64), orgid varchar(64));
create table t_emc_consume (id varchar(64) primary key, mtlname varchar(100), specification varchar(100), stockqty numeric, mtlcategoryid varchar(64), harmfulness varchar(36), productno varchar(64), createdbyid varchar(64), createdbyname varchar(100), createdtime timestamp, createdbyorgid varchar(64), createdbyorgname varchar(100));
create table t_emc_csm_stock (id bigint primary key, mtlid varchar(64), batchno varchar(64), stockqty numeric, unitname varchar(64), expiredate timestamp, lowlimit numeric, status varchar(4), createdbyid varchar(64), createdbyname varchar(100), createdtime timestamp, createdbyorgid varchar(64), createdbyorgname varchar(100));
create table t_emc_csm_stock_log (id bigint primary key, stockid bigint, logtype varchar(36), previousqty numeric, qty numeric, vendorid varchar(64), price numeric, logcontent varchar(200), receivedbyid varchar(64), receivedbyorgid varchar(64), createdbyid varchar(64), createdbyname varchar(100), createdtime timestamp, createdbyorgid varchar(64), createdbyorgname varchar(100));
create table t_core_report_config_line (id bigint primary key, reportname varchar(100), reportcategory varchar(100), reportpath varchar(200), param varchar(500), reportconfigid varchar(64), activatedflag varchar(1));

